package com.mybank.pbac.service;
import com.mybank.pbac.dto.PolicyTargetRequest; import com.mybank.pbac.model.*; import com.mybank.pbac.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class PolicyTargetService{private final PolicyTargetRepository repo;private final IndustryRepository industries;private final AuditService audit;public PolicyTargetService(PolicyTargetRepository r,IndustryRepository i,AuditService a){repo=r;industries=i;audit=a;}
 public List<PolicyTarget> all(){return repo.findAll();} public PolicyTarget save(Long id,PolicyTargetRequest r){PolicyTarget t=id==null?new PolicyTarget():repo.findById(id).orElseThrow();t.setIndustry(industries.findById(r.industryId()).orElseThrow(()->new NoSuchElementException("Industry not found")));t.setGuardrailType(r.guardrailType());t.setGuardrailSubtype(r.guardrailSubtype());t.setDecisionPath(r.decisionPath());t.setPolicyDataPath(r.policyDataPath());t.setEnabled(r.enabled()==null||r.enabled());t=repo.save(t);audit.log(id==null?"CREATE":"UPDATE","POLICY_TARGET",t.getId(),t.getDecisionPath());return t;} public void delete(Long id){repo.deleteById(id);}}
